mapper.select:
SELECT c.id, c.name, c.image, NULL AS appearance, NULL AS background, COUNT(ufc.character_id) AS followCount FROM user_follow_character ufc INNER JOIN app_character c ON ufc.character_id = c.id WHERE ufc.status = 1
AND ufc.create_time >= #{startTime}
AND ufc.create_time <= #{endTime}
GROUP BY c.id, c.name, c.image ORDER BY followCount DESC LIMIT #{limit}
